using System.Globalization;
using Pitt.Carry;
using UnityEngine;

namespace Pitt.OnePit
{
    /// Скорость, п. 4 (8д3-S): QA-прыжки для web e2e-бота — только с `-pittE2E` (без него ничего не делает).
    ///   -pittOpStack N — через 1 с зала герой стоит в точке броска у Ямы (D = max(дальность − 0,1; R + 1,5) м от центра, со стороны,
    ///                    где он стоял, лицом к Яме; кромка — автоброс — не задета), у ног N уток (подбирает сам). Пока герой в 3 м от
    ///                    этой точки, стопка пуста 1,5 с игры, попапа нет и коробки в руках нет — у ног снова N уток. Так «Скинуть»,
    ///                    «Кинуть», цель и Q идут без gather и ходьбы.
    /// Лог: `[PITT] [e2e] qa stack n=N at=x,z d=D` / `[PITT] [e2e] qa stack refill n=N t=…`.
    /// Ключ сразу (D keygift) — `-pittOpKeyNow [сек]` в PitGoal (QaKeyNow).
    public static class E2eQa
    {
        const float RefillIdle = 1.5f, Near = 3f;
        static int _n = -1;
        static bool _placed;
        static Vector3 _spot;
        static float _empty;
        public static int Refills;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        static void ResetStatics() { _n = -1; _placed = false; _empty = 0f; Refills = 0; }

        static int N { get { if (_n < 0) _n = E2eProbe.On && Args.Has("-pittOpStack") ? Mathf.Clamp(Args.GetI("-pittOpStack", 6), 0, 40) : 0; return _n; } }

        internal static void Tick()
        {
            if (N <= 0 || Game.IsSim || !OnePitFlow.Built || !Game.InGameplay) return;
            var pl = Game.Player;
            var pit = Game.Pit;
            var cs = CarryStack.Instance;
            if (pl == null || pit == null || cs == null) return;
            float now = OnePitState.HallTime;
            if (!_placed)
            {
                if (now < 1f) return;
                _placed = true;
                var dir = (pl.Position - pit.Center).Flat();
                if (dir.sqrMagnitude < 0.01f) dir = Vector3.back;
                dir.Normalize();
                float d = Mathf.Max(HallThrow.Range - 0.1f, pit.Radius + 1.5f);
                _spot = (pit.Center + dir * d).WithY(0f);
                pl.Frozen = false;
                pl.Teleport(_spot, Mathf.Atan2(-dir.x, -dir.z) * Mathf.Rad2Deg);
                Give(N);
                Debug.Log(string.Format(CultureInfo.InvariantCulture, "[PITT] [e2e] qa stack n={0} at={1:0.0},{2:0.0} d={3:0.0} t={4:0.0}", N, _spot.x, _spot.z, d, now));
                return;
            }
            bool idle = cs.Count == 0 && !PopupHost.AnyOpen && !HallCrates.Carrying && Ext.FlatDist(pl.Position, _spot) < Near;
            _empty = idle ? _empty + TimeCtl.Dt : 0f;
            if (_empty < RefillIdle) return;
            _empty = 0f;
            Refills++;
            Give(N);
            Debug.Log(string.Format(CultureInfo.InvariantCulture, "[PITT] [e2e] qa stack refill n={0} k={1} t={2:0.0}", N, Refills, now));
        }

        static void Give(int n)
        {
            var at = Game.Player.Position;
            for (int i = 0; i < n; i++)
            {
                float a = i * 2.39996f, r = 0.3f + 0.05f * i;
                var p = Product.Spawn(ProductKind.Duck, at + new Vector3(Mathf.Cos(a) * r, 0.3f, Mathf.Sin(a) * r), Quaternion.identity, false);
                if (p) p.Zone = HallProdDefs.Zone;
            }
        }
    }
}
